// KafkaJS Producer + Consumer (Node.js)
// KafkaJS is no longer actively maintained; Confluent's
// @confluentinc/kafka-javascript offers a KafkaJS-compatible API on librdkafka.
import { Kafka, Partitioners } from 'kafkajs';

const kafka = new Kafka({
  clientId: 'order-service',
  brokers: [process.env.KAFKA_BROKER ?? 'localhost:9092'],
});

// ── PRODUCER ──────────────────────────────────────────────────
const producer = kafka.producer({
  // Java-compatible murmur2 hashing: same key → same partition as other clients
  createPartitioner: Partitioners.DefaultPartitioner,
  idempotent: true, // broker drops duplicates caused by producer retries
  // (idempotence alone is NOT end-to-end exactly-once — see below)
});
await producer.connect();

async function publishOrderPlaced(order) {
  const record = await producer.send({
    topic: 'orders',
    messages: [
      {
        // Partition key: all events for the same order go to the same
        // partition, preserving per-order ordering across retries.
        key: String(order.id),
        value: JSON.stringify({
          eventType: 'order.placed',
          orderId: order.id,
          userId: order.userId,
          total: order.total,
          items: order.items,
          timestamp: Date.now(),
        }),
        // Headers carry metadata without bloating the payload
        headers: {
          'content-type': 'application/json',
          'schema-version': '2',
        },
      },
    ],
  });
  // Returns immediately — the API response is never blocked by downstream
  // processing. The message is durably stored on the Kafka broker.
  console.log('Published to partition', record[0].partition,
    'offset', record[0].baseOffset);
}

// ── CONSUMER (Notification Service) ───────────────────────────
const consumer = kafka.consumer({ groupId: 'notification-service' });
await consumer.connect();
await consumer.subscribe({ topic: 'orders', fromBeginning: false });

await consumer.run({
  // autoCommit: false  // set to false for manual offset control
  eachMessage: async ({ topic, partition, message }) => {
    const event = JSON.parse(message.value.toString());

    if (event.eventType === 'order.placed') {
      // Idempotency check — skip orders we already emailed
      const key = `notif:${event.orderId}`;
      if ((await redis.get(key)) === 'sent') {
        console.log('Duplicate, skipping', event.orderId);
        return; // offset gets committed — no redelivery
      }

      // Provider-side idempotency key covers a crash between send and mark
      await sendOrderConfirmationEmail(event.userId, event.orderId, {
        idempotencyKey: `order-placed-${event.orderId}`,
      });
      // Mark AFTER success: marking first would turn a failed send into
      // a silently skipped email on redelivery
      await redis.set(key, 'sent', 'EX', 86400);
      // KafkaJS auto-commits the offset after eachMessage resolves.
      // If sendEmail throws, the offset is NOT committed and Kafka
      // redelivers the message — at-least-once behaviour.
    }
  },
});

sections.content:
Since at-least-once is the practical default, **idempotent consumers** are the most important pattern in async system design. An operation is idempotent if running it multiple times with the same input produces the same result as running it once.

**Pattern 1: Idempotency key in a fast store**
Store a unique identifier for each processed message (a UUID embedded in the message, or `orderId` + event type) in Redis with a TTL. The subtle part is *when* to record it: mark too early and a failed attempt is skipped forever; mark too late and two consumers can both do the work. A claim-then-confirm pattern handles both:

```javascript
async function processIdempotent(event) {
  const key = `proc:${event.id}`;
  // Claim atomically (NX). The short TTL frees the claim if this worker
  // dies mid-work, so a later redelivery can try again.
  const claimed = await redis.set(key, 'processing', 'NX', 'EX', 300);
  if (!claimed) {
    if ((await redis.get(key)) === 'done') return; // true duplicate: ack + skip
    throw new Error('in progress elsewhere');      // don't ack: retry later
  }
  try {
    await doActualWork(event);
    await redis.set(key, 'done', 'EX', 86400);    // remember for 24 h
  } catch (err) {
    await redis.del(key);                          // release so a retry can claim it
    throw err;
  }
}
```

A crash between `doActualWork` and marking `done` still repeats the work on redelivery, so the work itself should also be idempotent (patterns 2–4) — the Redis key is a fast filter, not a guarantee.

**Pattern 2: Unique constraint in the database**
For events that write to a database, include the event ID as a unique column. A duplicate message will trigger a unique constraint violation on insert, which you catch and ignore. The database itself is the idempotency store — no separate Redis needed. Best of all, insert the processed-event row and do the business write in the **same transaction**: either both commit or neither does, which closes the crash window completely.

**Pattern 3: Upsert semantics**
Instead of INSERT, use an `INSERT ... ON CONFLICT DO UPDATE` (PostgreSQL) or equivalent. The second execution of the same message overwrites with the same data — idempotent by nature.

**Pattern 4: Natural idempotency**
Some operations are already idempotent. Setting a user's email address to a specific value is idempotent — do it twice, same result. Marking an order as 'shipped' (if it is already shipped, the second write is a no-op via a status check) can be made idempotent. Design your domain operations to be idempotent wherever possible, and the async messaging layer becomes much simpler to reason about.

**What idempotency does NOT solve**: ordering issues. If you receive `order.cancelled` before `order.placed` (possible if they land on different partitions), your consumer must handle out-of-order events. Using the same partition key for all events of the same entity (e.g., `orderId`) guarantees ordering within an entity — a critical design decision for event-driven systems.

